import {WIDTH,HEIGHT,COLS,ROWS,ROOMS,SPECIES,center,distance} from './data.js';
export class Renderer{
 constructor(canvas,game){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.game=game;this.images={};this.camera={x:0,y:0,zoom:1};this.selected=null;this.hover=null;this.card=null;this.gridVisible=false;this.time=0;this.bounds={x:0,y:0,tile:20};}
 image(name){if(!this.images[name]){const im=new Image();im.src=`assets/frames/${name}.png`;this.images[name]=im}return this.images[name]}
 sprite(name,x,y,w=1,h=1,flip=false,alpha=1){const im=this.image(name);if(!im.complete||!im.naturalWidth)return;const c=this.ctx,b=this.bounds,size=b.tile;c.save();c.globalAlpha=alpha;c.translate(Math.round(b.x+x*size),Math.round(b.y+y*size));if(flip){c.translate(w*size,0);c.scale(-1,1)}c.drawImage(im,0,0,Math.round(w*size),Math.round(h*size));c.restore()}
 point(x,y){return {x:this.bounds.x+x*this.bounds.tile,y:this.bounds.y+y*this.bounds.tile}}
 rect(x,y,w,h,color){const p=this.point(x,y);this.ctx.fillStyle=color;this.ctx.fillRect(Math.round(p.x),Math.round(p.y),Math.ceil(w*this.bounds.tile),Math.ceil(h*this.bounds.tile))}
 label(text,x,y,color='#c8baa4',size=10){const p=this.point(x,y),c=this.ctx;c.font=`${size}px "Segoe UI", sans-serif`;c.textAlign='center';c.fillStyle=color;c.fillText(text,p.x,p.y)}
 hit(clientX,clientY){const r=this.canvas.getBoundingClientRect(),b=this.bounds;return{x:(clientX-r.left-b.x)/b.tile,y:(clientY-r.top-b.y)/b.tile}}
 fit(){this.camera={x:0,y:0,zoom:1}}
 draw(delta){this.time+=delta;const canvas=this.canvas,c=this.ctx,rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr)}c.setTransform(dpr,0,0,dpr,0,0);c.imageSmoothingEnabled=false;const w=rect.width,h=rect.height,tile=Math.min(w/(WIDTH+1),h/(HEIGHT+1))*this.camera.zoom;this.bounds={tile,x:(w-WIDTH*tile)/2+this.camera.x,y:(h-HEIGHT*tile)/2+this.camera.y};c.fillStyle='#101313';c.fillRect(0,0,w,h);
  // Fine bedrock pattern remains subtle so the actual rooms carry the scene.
  c.strokeStyle='#1b1e1b';c.lineWidth=1;const spacing=tile*2;for(let y=(this.bounds.y%spacing)-spacing;y<h;y+=spacing)for(let x=(this.bounds.x%spacing)-spacing;x<w;x+=spacing){c.beginPath();c.moveTo(x+3,y+spacing-3);c.lineTo(x+spacing-3,y+spacing-3);c.moveTo(x+spacing-3,y+3);c.lineTo(x+spacing-3,y+spacing-3);c.stroke()}
  const game=this.game,s=game.state,frame=Math.floor(this.time*6)%4;
  for(let y=0;y<HEIGHT;y++)for(let x=0;x<WIDTH;x++)if(game.grid[y][x]){this.sprite('floor_'+(1+((x*13+y*29)%8)),x-.5,y-.5);this.rect(x-.5,y-.5,1,1,'#151b1925')}
  for(const r of s.rooms){const bx=2+r.col*8,by=2+r.row*8,def=ROOMS[r.type],p=center(r);this.rect(bx-.6,by-.55,7.2,7.15,'#00000055');
   for(let y=1;y<6;y++)for(let x=1;x<6;x++){const wx=bx+x,wy=by+y;this.sprite('floor_'+(1+((wx*13+wy*29)%8)),wx-.5,wy-.5);this.rect(wx-.5,wy-.5,1,1,r.type==='treasure'?'#9e682e15':r.type==='grave'?'#76689412':r.type==='mana'?'#386a7520':'#10161917')}
   for(let x=0;x<7;x++){if(!game.grid[by]?.[bx+x]){this.sprite(x===0?'wall_top_left':x===6?'wall_top_right':'wall_top_mid',bx+x-.5,by-1.1);this.sprite(x===0?'wall_left':x===6?'wall_right':'wall_mid',bx+x-.5,by-.1)}if(!game.grid[by+6]?.[bx+x])this.sprite('wall_top_mid',bx+x-.5,by+5.65)}
   for(let y=1;y<6;y++)for(const x of [0,6])if(!game.grid[by+y]?.[bx+x]){this.sprite(x===0?'wall_left':'wall_right',bx+x-.5,by+y-.5);this.rect(bx+x-.5,by+y-.5,1,1,'#080b0e35')}
   for(const off of [1,5]){const flame=frame;this.sprite(`wall_banner_${r.type==='treasure'?'yellow':r.type==='grave'?'blue':'red'}`,bx+off-.5,by-.1);const q=this.point(bx+off,by+1.2),grad=c.createRadialGradient(q.x,q.y,0,q.x,q.y,tile*2.1);grad.addColorStop(0,'#e8a74528');grad.addColorStop(1,'#e8a74500');c.fillStyle=grad;c.fillRect(q.x-tile*2.1,q.y-tile*2.1,tile*4.2,tile*4.2);this.rect(bx+off-.12,by+.62,.24,.14,'#a77548');this.rect(bx+off-.08,by+.32-Math.sin(this.time*10+off)*.07,.16,.3,'#df9b47');this.rect(bx+off-.04,by+.33,.08,.18,'#ffe4a3')}
   if(r.type==='entrance'){this.sprite('floor_stairs',p.x-1,p.y-1,2,2);this.sprite('column',bx+.25,by+3.4,1,2);this.sprite('column',bx+4.75,by+3.4,1,2)}
   if(r.type==='guard'){this.sprite('crate',bx+.7,by+1.4);this.sprite('crate',bx+1.65,by+1.4);this.sprite('weapon_spear',bx+4.5,by+1.25,.55,1.8);this.sprite('skull',bx+4.3,by+4.4,.7,.7)}
   if(r.type==='trap')for(const [dx,dy]of [[-1,-1],[1,-1],[0,0],[-1,1],[1,1]])this.sprite(`floor_spikes_anim_f${Math.floor(this.time*3+dx+dy+10)%4}`,p.x+dx-.5,p.y+dy-.5);
   if(r.type==='treasure'){this.rect(p.x-1.5,p.y-2,3,4,'#7a29303a');for(let i=0;i<4;i++)this.rect(p.x-1.5,p.y-2+i,3,.04,'#ad795240');this.sprite('column',bx+.35,by+2.6,1,2);this.sprite('column',bx+4.65,by+2.6,1,2);this.sprite('coin_anim_f'+frame,bx+1,by+4.5,.7,.7);this.sprite('coin_anim_f'+frame,bx+4.5,by+4.5,.7,.7)}
   if(r.type==='grave'){for(const [dx,dy]of [[-1.6,-.6],[1.4,-.6],[-1.6,1.6],[1.4,1.6]]){this.rect(p.x+dx-.4,p.y+dy-.15,.9,.5,'#39333e');this.sprite('skull',p.x+dx-.35,p.y+dy-.5,.7,.7)}this.sprite('column',p.x-.45,by+.35,1,2)}
   if(r.type==='mana'){this.sprite('wall_fountain_top_1',p.x-.5,by-.1);this.sprite('wall_fountain_mid_blue_anim_f'+frame%3,p.x-.5,by+.9);this.sprite('wall_fountain_basin_blue_anim_f'+frame%3,p.x-.5,by+1.9);const q=this.point(p.x,p.y);const gradient=c.createRadialGradient(q.x,q.y,2,q.x,q.y,tile*2.7);gradient.addColorStop(0,'#4aaebc26');gradient.addColorStop(1,'#4aaebc00');c.fillStyle=gradient;c.fillRect(q.x-tile*3,q.y-tile*3,tile*6,tile*6);this.sprite('flask_big_blue',bx+1,by+4.2,.7,.7)}
   if(r.type==='shop'){for(let i=1;i<5;i++)this.sprite('crate',bx+i-.3,by+1.5);this.sprite('flask_red',p.x-1.3,by+1,.6,.6);this.sprite('flask_blue',p.x+.6,by+1,.6,.6);this.sprite('doc_idle_anim_f'+frame,p.x-.5,p.y-.8,1,1.5)}
   if(r.type==='loot')this.sprite(r.loot?'chest_full_open_anim_f0':'chest_empty_open_anim_f2',p.x-.6,p.y-.5,1.2,1.2);
   this.label(def.name.toUpperCase(),p.x,by+7.15,def.color,Math.max(8,Math.min(10,tile*.46)));
   if(this.selected===r.id){const q=this.point(bx-.5,by-.5);c.strokeStyle='#dfbd78';c.lineWidth=1.5;c.strokeRect(q.x,q.y,7*tile,7*tile)}
  }
  if(this.card?.kind==='room')for(let row=0;row<ROWS;row++)for(let col=0;col<COLS;col++){if(s.rooms.some(r=>r.col===col&&r.row===row)||!s.rooms.some(r=>Math.abs(r.col-col)+Math.abs(r.row-row)===1))continue;const bx=2+col*8,by=2+row*8,q=this.point(bx-.5,by-.5);const active=this.hover&&Math.floor((this.hover.x-1.5)/8)===col&&Math.floor((this.hover.y-1.5)/8)===row;this.rect(bx-.5,by-.5,7,7,active?'#bd9b4d28':'#bd9b4d0c');c.strokeStyle=active?'#d7b476':'#80704e';c.setLineDash([4,5]);c.strokeRect(q.x,q.y,7*tile,7*tile);c.setLineDash([]);this.label('+',bx+3,by+3.5,active?'#e8c991':'#887854',26)}
  const treasureCarrier=s.entities.find(e=>e.id===s.treasure.carrier);const tp=treasureCarrier||s.treasure;if(!treasureCarrier){const q=this.point(tp.x,tp.y),pulse=.6+Math.sin(this.time*2)*.15;c.strokeStyle=`rgba(215,180,105,${pulse})`;c.beginPath();c.ellipse(q.x,q.y+tile*.25,tile*.85,tile*.35,0,0,Math.PI*2);c.stroke();this.sprite('chest_full_open_anim_f2',tp.x-.6,tp.y-.75,1.2,1.2)}
  for(const item of s.items.filter(i=>!i.owner&&i.x!==null))this.sprite('coin_anim_f'+frame,item.x-.3,item.y-.3,.6,.6);
  for(const e of [...s.entities].sort((a,b)=>a.y-b.y)){
   if(e.status==='escaped')continue;if(e.status==='downed'){this.sprite('skull',e.x-.35,e.y-.2,.7,.7,false,.45);continue}const def=SPECIES[e.species],q=this.point(e.x,e.y);c.fillStyle='#00000065';c.beginPath();c.ellipse(q.x,q.y+tile*.3,tile*.4,tile*.19,0,0,Math.PI*2);c.fill();
   if(this.selected===e.id){c.strokeStyle='#dfbd78';c.lineWidth=1.5;c.beginPath();c.ellipse(q.x,q.y+tile*.2,tile*.63,tile*.32,0,0,Math.PI*2);c.stroke()}
   const big=e.species==='lord',size=big?1.8:1.15,aspect=['slime'].includes(e.species)?1:big?1:1.5;const anim=e.species==='slime'?`tiny_slug_anim_f${frame}`:`${def.sprite}_${e.moving?'run':'idle'}_anim_f${frame}`;this.sprite(anim,e.x-size/2+(e.strike?Math.sin(e.strike*16)*.15:0),e.y-size*aspect+.43,size,size*aspect,e.flip);if(e.evolution)this.sprite('weapon_golden_sword',e.x+.3,e.y-1,.35,1);
   if(e.hp<e.maxHp||this.selected===e.id||e.faction==='hero'){this.rect(e.x-.55,e.y-size*aspect+.13,1.1,.13,'#090c0c');this.rect(e.x-.55,e.y-size*aspect+.13,1.1*e.hp/e.maxHp,.11,e.faction==='monster'?'#94ad79':'#c47a67')}
   if(this.selected===e.id)this.label(e.name,e.x,e.y+1,'#e1d0b2',11);if(e.teleport>0){c.strokeStyle='#bba2e8';c.beginPath();c.ellipse(q.x,q.y,tile*(.8+e.teleport*.15),tile*.5,0,0,Math.PI*2);c.stroke();this.label(`DỊCH CHUYỂN ${Math.ceil(3-e.teleport)}s`,e.x,e.y-2,'#bba2e8',9)}if(treasureCarrier===e)this.sprite('chest_full_open_anim_f2',e.x-.4,e.y-2.6,.8,.8);
  }
  if(this.gridVisible){c.strokeStyle='#a4bcb51d';for(let y=0;y<HEIGHT;y++)for(let x=0;x<WIDTH;x++)if(game.grid[y][x]){const p=this.point(x-.5,y-.5);c.strokeRect(p.x,p.y,tile,tile)}const e=s.entities.find(e=>e.id===this.selected);if(e?.path.length){c.strokeStyle='#91c7c0';c.beginPath();const p=this.point(e.x,e.y);c.moveTo(p.x,p.y);for(const pt of e.path){const q=this.point(pt.x,pt.y);c.lineTo(q.x,q.y)}c.stroke()}}
  for(const f of game.effects){if(f.beam){const p=this.point(f.x,f.y-.5),q=this.point(f.tx,f.ty-.5);c.strokeStyle=f.color;c.lineWidth=2;c.beginPath();c.moveTo(p.x,p.y);c.lineTo(q.x,q.y);c.stroke()}else this.label(f.text,f.x,f.y-1.3-(1-f.life)*.7,f.color,13)}
  // Dim the edges, keeping the rooms warm and readable.
  const vignette=c.createRadialGradient(w/2,h/2,Math.min(w,h)*.2,w/2,h/2,Math.max(w,h)*.65);vignette.addColorStop(0,'#00000000');vignette.addColorStop(1,'#00000070');c.fillStyle=vignette;c.fillRect(0,0,w,h);
 }
}
